await page.selectOption('[aria-label="Category"], select >> nth=0', 'Tents');
await page.getByLabel('Minimum rating').selectOption('4+');
await page.getByLabel('In stock only').check();
await page.getByLabel('Sort').selectOption({label:'Price: low to high'});
await page.getByRole('button',{name:'Apply filters'}).click();
await page.waitForTimeout(800);
return await page.locator('main').innerText();
}

async (page) => {
await page.getByLabel('Category').selectOption('All');
await page.getByLabel('Minimum rating').selectOption('Any');
await page.getByLabel('In stock only').uncheck();
await page.getByLabel('Sort').selectOption('Featured');
await page.getByRole('button',{name:'Apply filters'}).click();
await page.waitForTimeout(500);
const n = await page.locator('main button', {hasText:/^\d+$/}).count();
let out=[];
for (let i=1;i<=n;i++){ await page.getByRole('button',{name:String(i),exact:true}).click(); await page.waitForTimeout(400);
 out.push(...(await page.locator('main').innerText()).split('Apply filters')[1].split('\n').filter(x=>x)); }
const t=out.join('|');
return t.match(/[^|]*Tent[^|]*\|[^|]*\|[^|]*\|[^|]*/g).filter(x=>/In stock$/.test(x));
}

